plugins {
    id("com.github.jakemarsden.git-hooks") version "0.0.2"
    id("com.diffplug.spotless") version "6.25.0"

    // Apply the cpp-application plugin to add support for building C++ executables
    `cpp-application`

    // Apply the cpp-unit-test plugin to add support for building and running C++ test executables
    `cpp-unit-test`
}

// Configurazione base del progetto
repositories {
    mavenCentral()
}

dependencies {
    // Aggiungi qui le tue dipendenze
    //implementation("com.diffplug.spotless:spotless-plugin-gradle:6.25.0")
}

// Set the target operating system and architecture for this application
application {
    targetMachines.add(machines.linux.x86_64)
}

// Configurazione Spotless per C++
spotless {
    cpp {
        target("app/src/main/cpp/*.cpp", "app/src/main/headers/*.h")
        clangFormat()
    }
}

// Configurazione Git Hooks
gitHooks {
    setHooks(mapOf("pre-commit" to "check"))
    setHooks(mapOf("commit-msg" to "conventionalCommits"))
}

fun conventionalCommits() {
    val pattern = Pattern.compile("^(feat|fix|docs|style|refactor|test|chore)(\\(.*\\))?: .{1,50}")
    val message = File(".git/COMMIT_EDITMSG").readText().trim()
    if (!pattern.matcher(message).find()) {
        throw GradleException("Commit message does not follow Conventional Commits format.")
    }
}

tasks.register("buildCMake") {
    doLast {
        exec {
            commandLine("sh", "-c", """
                mkdir -p build &&
                cd build &&
                cmake .. &&
                cmake --build .
            """)
        }
    }
}

tasks.register("installPreCommit") {
    doLast {
        val os = org.gradle.nativeplatform.platform.internal.DefaultNativePlatform.getCurrentOperatingSystem()
        if (os.isWindows) {
            exec {
                commandLine(
                    "cmd", "/c", """
                    curl https://github.com/pre-commit/pre-commit/releases/download/v3.7.1/pre-commit-3.7.1.pyz -o pre-commit &&
                    powershell -Command "Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass" &&
                    powershell -Command "chmod +x pre-commit" &&
                    powershell -Command "./pre-commit install"
                """)
            }
        } else {
            exec {
                commandLine(
                    "sh", "-c", """
                    curl https://github.com/pre-commit/pre-commit/releases/download/v3.7.1/pre-commit-3.7.1.pyz -o pre-commit &&
                    chmod +x pre-commit &&
                    ./pre-commit install
                """)
            }
        }
    }
}

unitTest {
    targetMachines.add(machines.linux.x86_64)
}

// Configura cpp-application per usare l'output di CMake
tasks.withType<LinkExecutable>().configureEach {
    dependsOn("buildCMake")
    linkerArgs.addAll(listOf(
        "-L/usr/local/lib",
        "-lopencv_core",
        "-lopencv_imgproc",
        "-lopencv_objdetect",
        "-lopencv_highgui",
        "-lopencv_imgcodecs",
        "-lopencv_videoio"
    ))
    linkerArgs.add("-Wl,-rpath,/usr/local/lib")
}

tasks.withType<CppCompile>().configureEach {
    dependsOn("buildCMake")
    includes.from("/usr/local/include/opencv4")
}

// Assicurati che i git hooks vengano installati durante il build
tasks.getByPath(":prepareKotlinBuildScriptModel").dependsOn
    .addAll(listOf(tasks.getByName("check"), tasks.getByName("installPreCommit")))